class Solution {
public:
    vector<int> lastVisitedIntegers(vector<int>& nums) {
        vector<int> seen, ans;
        int k = 0;
        for (int x : nums) {
            if (x > 0) {
                seen.push_back(x);
                k = 0;
            } else {
                k++;
                if (k <= seen.size()) ans.push_back(seen[seen.size() - k]);
                else ans.push_back(-1);
            }
        }
        return ans;
    }
};

class Solution {
    public List<Integer> lastVisitedIntegers(List<Integer> nums) {
        List<Integer> seen = new ArrayList<>();
        List<Integer> ans = new ArrayList<>();
        int k = 0;
        for (int x : nums) {
            if (x > 0) {
                seen.add(x);
                k = 0;
            } else {
                k++;
                if (k <= seen.size()) ans.add(seen.get(seen.size() - k));
                else ans.add(-1);
            }
        }
        return ans;
    }
}

/**
 * @param {number[]} nums
 * @return {number[]}
