var lastVisitedIntegers = function(nums) {
    const seen = [];
    const ans = [];
    let k = 0;
    for (const x of nums) {
        if (x > 0) {
            seen.push(x);
            k = 0;
        } else {
            k++;
            if (k <= seen.length) ans.push(seen[seen.length - k]);
            else ans.push(-1);
        }
    }
    return ans;
};
